static const Case CASES[] = {
    { "plain", f_plain, sizeof f_plain, e_plain, 32, 24, 3072, 0 },
    { "interlaced", f_interlaced, sizeof f_interlaced, e_interlaced, 32, 24, 3072, 1 },
    { "transparent", f_transparent, sizeof f_transparent, e_transparent, 32, 24, 3072, 0 },
    { "large128x96", f_large128x96, sizeof f_large128x96, e_large128x96, 128, 96, 49152, 0 },
};

int main(void) {
    printf("=== wubu_gif (slerm gate, SLERM-2021 stage A) ===\n");
    for (size_t i = 0; i < sizeof CASES / sizeof CASES[0]; i++) {
        const Case *c = &CASES[i];
        WubuGif info = {0};
        int err = 0;
        if (wubu_gif_info(c->file, c->flen, &info, &err) != 0) {
            printf("  [FAIL] %-12s info: %s\n", c->name, wubu_gif_reason(err)); fail++; continue;
        }
        if (info.width != c->w || info.height != c->h || info.channels != 4 ||
            info.interlaced != c->interlaced) {
            printf("  [FAIL] %-12s info %dx%d/%dch interlace=%d\n", c->name,
                   info.width, info.height, info.channels, info.interlaced); fail++; continue;
        }
        size_t need = (size_t)c->w * c->h * 4;
        unsigned char *out = malloc(need);
        if (wubu_gif_decode(c->file, c->flen, out, need, &info, &err) != 0) {
            printf("  [FAIL] %-12s decode: %s\n", c->name, wubu_gif_reason(err)); free(out); fail++; continue;
        }
        if (!memcmp(out, c->expect, need)) pass++;
        else { printf("  [FAIL] %-12s pixels differ\n", c->name); fail++; }
        free(out);
    }

    /* refusals */
    {
        unsigned char out[32 * 24 * 4];
        WubuGif info = {0};
        int err = 0;
        if (wubu_gif_decode(f_trunc, sizeof f_trunc, out, sizeof out, &info, &err) != 0 &&
            (err == WUBU_GIF_TRUNCATED || err == WUBU_GIF_CORRUPT)) pass++;
        else { printf("  [FAIL] truncated accepted (err %d)\n", err); fail++; }

        err = 0;
        static const unsigned char junk[] = { 'N','O','T','A','G','I','F','8','9','a',0,0,0 };
        if (wubu_gif_decode(junk, sizeof junk, out, sizeof out, &info, &err) != 0 && err == WUBU_GIF_FORMAT) pass++;
        else { printf("  [FAIL] non-GIF accepted (err %d)\n", err); fail++; }

        err = 0;
        if (wubu_gif_decode(f_plain, sizeof f_plain, out, 8, &info, &err) != 0 && err == WUBU_GIF_OVERFLOW) pass++;
        else { printf("  [FAIL] undersized buffer accepted (err %d)\n", err); fail++; }

        err = 0;
        if (wubu_gif_decode(f_corrupt, sizeof f_corrupt, out, sizeof out, &info, &err) != 0) pass++;
        else { printf("  [FAIL] corrupt stream decoded without complaint\n"); fail++; }
    }

    printf("\n=== %d passed, %d failed ===\n", pass, fail);
    return fail ? 1 : 0;
}
